import _codecs
class Meta(type):
    def __getattribute__(self, name):
        raise AssertionError('metaclass attribute lookup')
class C(metaclass=Meta):
    pass
value = iter([])
for data in ('', 'A', 'é'):
    for invoke in (
        lambda: data.encode(value),
        lambda: data.encode(encoding=value),
        lambda: str.encode(data, encoding=value),
    ):
        try:
            invoke()
        except TypeError as error:
            assert error.args == ("encode() argument 'encoding' must be str, not list_iterator",), error.args
        else:
            raise AssertionError('invalid codec argument accepted')
    for invoke in (
        lambda: _codecs.encode(data, value),
        lambda: _codecs.encode(data, encoding=value),
    ):
        try:
            invoke()
        except TypeError as error:
            assert error.args == ("encode() argument 'encoding' must be str, not list_iterator",), error.args
        else:
            raise AssertionError('invalid registry argument accepted')
    for invoke, expected_type in (
        (lambda: bytes(data, value), "list_iterator"),
        (lambda: bytes(data, encoding=value), "list_iterator"),
    ):
        try:
            invoke()
        except TypeError as error:
            assert error.args == ("bytes() argument 'encoding' must be str, not " + expected_type,), error.args
        else:
            raise AssertionError('invalid constructor argument accepted')

